 public static string Capture(){string dir="Screenshots/InteriorReview/Corrected";Directory.CreateDirectory(dir);var g=new GameObject("Temporary interior inspection camera");var c=g.AddComponent<Camera>();c.fieldOfView=66;c.nearClipPlane=.04f;c.farClipPlane=90;c.allowHDR=true;var rt=new RenderTexture(1600,1000,24);var prev=RenderTexture.active;try{c.targetTexture=rt;var pos=new[]{new Vector3(-2.4f,2.1f,3.8f),new Vector3(-2.8f,2.1f,8.3f),new Vector3(-2.3f,2.1f,12.8f),new Vector3(-3.6f,2.15f,16.7f),new Vector3(-2.5f,2.1f,5.6f)};var target=new[]{new Vector3(-2.4f,2.1f,17),new Vector3(1.15f,1.85f,8.5f),new Vector3(1.1f,2,13.6f),new Vector3(-1.8f,1.75f,20),new Vector3(-6.5f,2,6.7f)};for(int i=0;i<pos.Length;i++){g.transform.position=pos[i];g.transform.LookAt(target[i]);c.Render();c.Render();RenderTexture.active=rt;var t=new Texture2D(1600,1000,TextureFormat.RGB24,false);try{t.ReadPixels(new Rect(0,0,1600,1000),0,0);t.Apply();File.WriteAllBytes(dir+"/View"+i+".png",t.EncodeToPNG());}finally{UnityEngine.Object.DestroyImmediate(t);}}}finally{RenderTexture.active=prev;c.targetTexture=null;UnityEngine.Object.DestroyImmediate(g);UnityEngine.Object.DestroyImmediate(rt);}return dir;}
